# Choose a shortest sequence of doors through a gallery floor
# plan. A predecessor table is also the visited set, preventing loops from
# repeatedly entering the queue. Sorting neighbors establishes a
# reproducible tie rule. A missing exit returns None, while starting at an
# exit returns a one-element route.

from collections import deque

def route_to_exit(graph, start, exits):
    queue = deque([start])
    parent = {start: None}
    while queue:
        node = queue.popleft()
        if node in exits:
            path = []
            while node is not None:
                path.append(node)
                node = parent[node]
            return path[::-1]
        for neighbor in sorted(graph.get(node, ())):
            if neighbor not in parent:
                parent[neighbor] = node
                queue.append(neighbor)
    return None

hall = {"desk": ["door", "stairs"], "stairs": ["desk", "yard"]}
assert route_to_exit(hall, "desk", {"yard"}) == ["desk", "stairs", "yard"]
assert route_to_exit(hall, "door", {"yard"}) is None

# Compress neighboring identical stage cues without merging later
# repetitions that occur after a different cue. Expansion checks a fixed
# output limit before allocating repeated values. The encoded representation
# is structural data, not an ambiguous concatenated string. These checks
# make empty and malformed sequences distinguishable.

def pack_runs(items):
    output = []
    for item in items:
        if output and output[-1][0] == item:
            output[-1][1] += 1
        else:
            output.append([item, 1])
    return output

def unpack_runs(runs, limit=100):
    output = []
    for item, count in runs:
        if type(count) is not int or count <= 0:
            raise ValueError("invalid run length")
        if len(output) + count > limit:
            raise ValueError("expanded sequence exceeds limit")
        output.extend([item] * count)
    return output

source = ["north", "north", "east", "north"]
assert unpack_runs(pack_runs(source)) == source
assert pack_runs([]) == []

# Build a search index for exhibit captions while keeping the first display
# spelling. Whitespace folding and case folding define the matching rule;
# neither proves that captions describe the same exhibit. A separate
# collision report exposes all competing spellings so that normalization
# does not conceal uncertain matches.

def stable_unique_labels(labels):
    seen = set()
    answer = []
    for label in labels:
        normalized = " ".join(label.split()).casefold()
        if normalized and normalized not in seen:
            seen.add(normalized)
            answer.append((normalized, label))
    return answer

def collisions(labels):
    groups = {}
    for label in labels:
        key = " ".join(label.split()).casefold()
        groups.setdefault(key, []).append(label)
    return {key: group for key, group in groups.items() if len(group) > 1}

assert stable_unique_labels(["  Blue  Box", "blue box", "Red"]) == [
    ("blue box", "  Blue  Box"), ("red", "Red")]
assert len(collisions(["Tea", "TEA", "tea"])) == 1

// Index a set of workshop cards by subject tags. Duplicate tags on
// one card create only one reference. Intersections preserve the first
// requested tag list order, and an unknown tag yields no matches. An empty
// query is defined as no search, rather than an implicit request for every
// stored card.

function indexCards(cards) {
  const byTag = new Map();
  for (const { id, tags } of cards) {
    for (const tag of new Set(tags)) {
      if (!byTag.has(tag)) byTag.set(tag, []);
      byTag.get(tag).push(id);
    }
  }
  return byTag;
}
function commonCards(index, wanted) {
  if (wanted.length === 0) return [];
  const groups = wanted.map(tag => new Set(index.get(tag) ?? []));
  return [...groups[0]].filter(id => groups.every(group => group.has(id)));
}
const index = indexCards([
  { id: 'c1', tags: ['paper', 'blue', 'blue'] },
  { id: 'c2', tags: ['paper'] },
  { id: 'c3', tags: ['blue'] },
]);
console.assert(commonCards(index, ['paper', 'blue']).join() === 'c1');
console.assert(commonCards(index, ['absent']).length === 0);

// Extract complete sampling windows from a hand-drawn altitude profile.
// Width and stride are positive integers, and incomplete trailing windows
// are excluded. Each result includes original coordinates as well as copied
// values. This distinction matters when an annotation must be placed back
// onto the full profile.

function rectangularWindows(items, width, step = 1) {
  if (!Number.isInteger(width) || width <= 0) throw new RangeError('width');
  if (!Number.isInteger(step) || step <= 0) throw new RangeError('step');
  const windows = [];
  for (let start = 0; start + width <= items.length; start += step) {
    windows.push({ start, end: start + width, values: items.slice(start, start + width) });
  }
  return windows;
}
const temperatures = [8, 9, 11, 10, 7, 6, 9];
const windows = rectangularWindows(temperatures, 3, 2);
const means = windows.map(({ values }) => values.reduce((a, b) => a + b, 0) / values.length);
console.assert(windows.length === 3);
console.assert(windows[1].start === 2);
console.assert(means[0] === 28 / 3);
console.assert(rectangularWindows([], 2).length === 0);

// Compare dotted inventory-release numbers as integer components rather than
// decimal fractions. A missing trailing component means zero. BigInt keeps
// unusually large component values exact. The accepted grammar excludes
// prerelease labels and signs, so this helper should not be mistaken for a
// complete semantic-version parser.

function compareVersions(left, right) {
  const parse = text => {
    if (!/^\d+(\.\d+)*$/.test(text)) throw new Error('invalid version');
    return text.split('.').map(part => BigInt(part));
  };
  const a = parse(left), b = parse(right);
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const x = a[i] ?? 0n, y = b[i] ?? 0n;
    if (x < y) return -1;
    if (x > y) return 1;
  }
  return 0;
}
const versions = ['2.10', '2.2.0', '2.2', '10.0'];
versions.sort(compareVersions);
console.assert(versions.join('|') === '2.2.0|2.2|2.10|10.0');
console.assert(compareVersions('0002.0', '2') === 0);
console.assert(compareVersions('9007199254740993', '9007199254740992') === 1);

// Collect adjacent runs of identical machine states in an event
// journal. A state that reappears later creates another group. Both endpoint
// times are retained, but no duration is inferred for events after the final
// observation. Source order is accepted as authoritative and is not repaired
// by sorting.

function groupAdjacent(events) {
  const groups = [];
  for (const event of events) {
    const last = groups.at(-1);
    if (last && last.type === event.type) {
      last.ids.push(event.id);
      last.lastTime = event.time;
    } else {
      groups.push({ type: event.type, ids: [event.id], firstTime: event.time, lastTime: event.time });
    }
  }
  return groups;
}
const events = [
  { id: 1, type: 'open', time: 2 },
  { id: 2, type: 'open', time: 3 },
  { id: 3, type: 'close', time: 8 },
  { id: 4, type: 'open', time: 9 },
];
const groups = groupAdjacent(events);
console.assert(groups.length === 3);
console.assert(groups[0].ids.join() === '1,2');
console.assert(groups[2].firstTime === 9);
console.assert(groupAdjacent([]).length === 0);

// Rotate a discussion order, then weave two proposed orders together without
// losing the longer tail. Negative distances rotate in the opposite
// direction. Fresh arrays keep these operations from changing the original
// schedule. Repeated names are ordinary entries here; resolving duplicate
// participants is a separate policy.

function rotateQueue(queue, distance) {
  if (!Number.isInteger(distance)) throw new TypeError('integer distance');
  if (queue.length === 0) return [];
  const offset = ((distance % queue.length) + queue.length) % queue.length;
  return queue.slice(offset).concat(queue.slice(0, offset));
}
function interleave(left, right) {
  const output = [];
  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    if (i < left.length) output.push(left[i]);
    if (i < right.length) output.push(right[i]);
  }
  return output;
}
const queue = ['amber', 'birch', 'cove'];
console.assert(rotateQueue(queue, -1).join() === 'cove,amber,birch');
console.assert(rotateQueue(queue, 3).join() === queue.join());
console.assert(interleave([1, 3, 5], [2]).join() === '1,2,3,5');

// Serialize a tiny exhibition inventory as a CSV table with an explicitly
// chosen column order. Embedded quotes are doubled, and cells with
// separators or line breaks are quoted. Missing values become empty cells
// while numeric zero survives. Formula interpretation by spreadsheet
// applications is outside this text-format example.

function escapeCell(value) {
  const text = String(value);
  return /[",\r\n]/.test(text) ? '"' + text.replaceAll('"', '""') + '"' : text;
}
function writeTable(rows, columns) {
  const header = columns.map(escapeCell).join(',');
  const body = rows.map(row => columns.map(key => escapeCell(row[key] ?? '')).join(','));
  return [header, ...body].join('\r\n') + '\r\n';
}
const table = writeTable([
  { item: 'cup, small', note: 'line 1\nline 2', count: 2 },
  { item: '"plain"', count: 0 },
], ['item', 'count', 'note']);
console.assert(table.startsWith('item,count,note\r\n'));
console.assert(table.includes('"cup, small",2,"line 1\nline 2"'));
console.assert(table.includes('"""plain""",0,'));

// Multiply a sparse collection of weighted links by a vector of available
// resources. Repeated coordinates contribute additively, including
// cancellations. Shape checks happen before indexing, and unmentioned output
// rows remain zero. The coordinate list is not modified, allowing it to be
// reused with a different vector.

function sparseProduct(entries, vector, rows) {
  if (!Number.isInteger(rows) || rows < 0) throw new RangeError('row count');
  const result = Array(rows).fill(0);
  for (const [r, c, value] of entries) {
    if (!Number.isInteger(r) || !Number.isInteger(c) || r < 0 || r >= rows || c < 0 || c >= vector.length) {
      throw new RangeError('entry outside shape');
    }
    result[r] += value * vector[c];
  }
  return result;
}
const entries = [[0, 1, 3], [2, 0, 4], [0, 1, -1], [1, 2, 5]];
const result = sparseProduct(entries, [2, 7, 0], 4);
console.assert(result.join() === '14,0,8,0');
console.assert(sparseProduct([], [], 2).join() === '0,0');
console.assert(entries.length === 4);

// Maintain undo and redo stacks for immutable draft labels. Creating a new
// label after undo discards the abandoned future, so redo cannot resurrect a
// different branch accidentally. A failed navigation leaves the current
// label intact. Mutable nested objects would require an additional copying
// or persistence policy.

function undoLog(initial) {
  let current = initial;
  const previous = [], next = [];
  return {
    value: () => current,
    set(value) {
      previous.push(current);
      current = value;
      next.length = 0;
    },
    undo() {
      if (!previous.length) return false;
      next.push(current);
      current = previous.pop();
      return true;
    },
    redo() {
      if (!next.length) return false;
      previous.push(current);
      current = next.pop();
      return true;
    },
  };
}
const log = undoLog('draft');
log.set('review'); log.set('ready');
console.assert(log.undo() && log.value() === 'review');
log.set('revised');
console.assert(log.redo() === false);
console.assert(log.undo() && log.value() === 'review');

// Rank words in a weather notebook by frequency, breaking ties by
// first appearance. A top-k request includes every entry tied at the cutoff,
// so its output can contain more than k entries. This is useful for an
// honest tied display but differs from selecting exactly k winners.

function frequencyOrder(words) {
  const counts = new Map();
  const first = new Map();
  words.forEach((word, index) => {
    if (!first.has(word)) first.set(word, index);
    counts.set(word, (counts.get(word) ?? 0) + 1);
  });
  return [...counts].sort((a, b) => b[1] - a[1] || first.get(a[0]) - first.get(b[0]));
}
function topWithTies(rows, limit) {
  if (limit <= 0 || rows.length === 0) return [];
  const cutoff = rows[Math.min(limit, rows.length) - 1][1];
  return rows.filter(([, count]) => count >= cutoff);
}
const ordered = frequencyOrder(['rain', 'sun', 'rain', 'fog', 'sun', 'hail']);
console.assert(ordered[0][0] === 'rain');
console.assert(topWithTies(ordered, 1).length === 2);
console.assert(frequencyOrder([]).length === 0);

// Parse an allowlisted set of name-value options without invoking any
// command. Empty values remain valid. Unknown names, malformed tokens, and
// repeated names are reported; the first accepted value wins. Error
// collection continues after a bad token so a caller can display several
// issues together.

function parseFlags(tokens, allowed) {
  const flags = new Map();
  const errors = [];
  for (const token of tokens) {
    const match = /^--([a-z][a-z-]*)=(.*)$/.exec(token);
    if (!match || !allowed.has(match[1])) {
      errors.push({ token, reason: 'unknown-or-malformed' });
      continue;
    }
    const [, name, value] = match;
    if (flags.has(name)) errors.push({ token, reason: 'duplicate' });
    else flags.set(name, value);
  }
  return { flags, errors };
}
const parsed = parseFlags(['--color=blue', '--empty=', '--color=red', '--other=x'], new Set(['color', 'empty']));
console.assert(parsed.flags.get('color') === 'blue');
console.assert(parsed.flags.get('empty') === '');
console.assert(parsed.errors.length === 2);

// Summarize valid readings from an observatory log. First and last refer
// to accepted input order, not necessarily chronological extremes. A second
// return value distinguishes a real mean of zero from the absence of any
// usable observation. Invalid readings remain part of the caller-owned
// source slice.

package main

import "fmt"

type Reading struct { Tick int; Value float64; Valid bool }
type Summary struct { First, Last int; Mean float64; Count int }

func summarize(rows []Reading) (Summary, bool) {
    var out Summary
    var total float64
    for _, row := range rows {
        if !row.Valid { continue }
        if out.Count == 0 { out.First = row.Tick }
        out.Last = row.Tick
        total += row.Value
        out.Count++
    }
    if out.Count == 0 { return out, false }
    out.Mean = total / float64(out.Count)
    return out, true
}

func main() {
    rows := []Reading{{1, 0, true}, {2, 99, false}, {5, 8, true}}
    result, ok := summarize(rows)
    fmt.Println(ok, result.First, result.Last, result.Mean, result.Count)
    _, empty := summarize(nil)
    fmt.Println(empty)
}

// Pack shipping weights into the first available box after sorting
// from heavy to light. This heuristic does not promise a minimum number of
// boxes. A copied work slice preserves the original order, and rejected
// parcels are returned explicitly rather than vanishing from capacity
// statistics.

package main

import ("fmt"; "sort")

type Parcel struct { Name string; Weight int }
func fillBoxes(parcels []Parcel, capacity int) ([][]Parcel, []Parcel) {
    work := append([]Parcel(nil), parcels...)
    sort.SliceStable(work, func(i, j int) bool { return work[i].Weight > work[j].Weight })
    boxes := [][]Parcel{}
    used := []int{}
    rejected := []Parcel{}
    for _, parcel := range work {
        if parcel.Weight <= 0 || parcel.Weight > capacity {
            rejected = append(rejected, parcel); continue
        }
        placed := false
        for i := range boxes {
            if used[i] + parcel.Weight <= capacity {
                boxes[i] = append(boxes[i], parcel); used[i] += parcel.Weight
                placed = true; break
            }
        }
        if !placed { boxes = append(boxes, []Parcel{parcel}); used = append(used, parcel.Weight) }
    }
    return boxes, rejected
}
func main() {
    boxes, bad := fillBoxes([]Parcel{{"a", 6}, {"b", 4}, {"c", 11}, {"d", 3}}, 10)
    fmt.Println(len(boxes), len(bad))
}

// Split sample sizes into below-pivot, equal-pivot, and above-pivot groups
// while preserving order inside each group. Concatenation creates a separate
// result with precomputed capacity. This operation is a stable partition,
// not a full sort, and repeated pivot values retain their original relative
// positions.

package main

import "fmt"

func stablePartition(values []int, pivot int) ([]int, []int, []int) {
    lower, equal, higher := []int{}, []int{}, []int{}
    for _, value := range values {
        switch {
        case value < pivot: lower = append(lower, value)
        case value == pivot: equal = append(equal, value)
        default: higher = append(higher, value)
        }
    }
    return lower, equal, higher
}
func concatenate(groups ...[]int) []int {
    total := 0
    for _, group := range groups { total += len(group) }
    result := make([]int, 0, total)
    for _, group := range groups { result = append(result, group...) }
    return result
}
func main() {
    values := []int{8, 3, 5, 2, 5, 9}
    a, b, c := stablePartition(values, 5)
    fmt.Println(a, b, c, concatenate(a, b, c))
    fmt.Println(values)
}

// Lay out a short banner without splitting individual words. Width counts
// Unicode scalar values rather than bytes or terminal columns. A word wider
// than the limit occupies its own line instead of being truncated. Rejecting
// a nonpositive width prevents a meaningless layout request from being
// treated as success.

package main

import ("fmt"; "strings")

func wrapWords(words []string, width int) ([]string, error) {
    if width < 1 { return nil, fmt.Errorf("width must be positive") }
    lines, current := []string{}, []string{}
    length := 0
    flush := func() { if len(current) > 0 { lines = append(lines, strings.Join(current, " ")); current = nil; length = 0 } }
    for _, word := range words {
        size := len([]rune(word))
        if size == 0 { continue }
        extra := size
        if len(current) > 0 { extra++ }
        if length + extra > width { flush(); extra = size }
        current = append(current, word)
        length += extra
        if size > width { flush() }
    }
    flush()
    return lines, nil
}
func main() {
    lines, err := wrapWords([]string{"small", "clouds", "over", "water"}, 11)
    fmt.Println(lines, err)
}

// Compute nonnegative shortest-path costs in a tiny canal network.
// The unreachable marker is kept out of additions, and candidate sums are
// checked against integer overflow. Edges reached by the search are
// validated; this is not a whole-graph validation pass for disconnected
// components.

package main

import "fmt"

type Edge struct { To int; Cost int }
func cheapestPaths(graph [][]Edge, start int) ([]int, error) {
    if start < 0 || start >= len(graph) { return nil, fmt.Errorf("bad start") }
    const infinity = int(^uint(0) >> 1)
    distance := make([]int, len(graph))
    used := make([]bool, len(graph))
    for i := range distance { distance[i] = infinity }
    distance[start] = 0
    for range graph {
        node := -1
        for i := range graph { if !used[i] && (node < 0 || distance[i] < distance[node]) { node = i } }
        if node < 0 || distance[node] == infinity { break }
        used[node] = true
        for _, edge := range graph[node] {
            if edge.To < 0 || edge.To >= len(graph) || edge.Cost < 0 { return nil, fmt.Errorf("bad edge") }
            if edge.Cost <= infinity-distance[node] && distance[node]+edge.Cost < distance[edge.To] {
                distance[edge.To] = distance[node]+edge.Cost
            }
        }
    }
    return distance, nil
}
func main() { result, err := cheapestPaths([][]Edge{{{1, 4}, {2, 9}}, {{2, 2}}, {}}, 0); fmt.Println(result, err) }

// Compare two snapshots of a seed inventory. A quantity changing
// to zero is an update rather than a deletion. Removed keys follow their
// first appearance in the old snapshot, while changed records follow the new
// snapshot order. Duplicate-key behavior is intentionally visible in the
// implementation.

package main

import "fmt"

type Pair struct { Key string; Value int }
func changes(before, after []Pair) ([]Pair, []string) {
    old := make(map[string]int)
    for _, row := range before { old[row.Key] = row.Value }
    changed, removed := []Pair{}, []string{}
    present := make(map[string]bool)
    for _, row := range after {
        value, found := old[row.Key]
        if !found || value != row.Value { changed = append(changed, row) }
        present[row.Key] = true
    }
    seen := make(map[string]bool)
    for _, row := range before {
        if !present[row.Key] && !seen[row.Key] { removed = append(removed, row.Key); seen[row.Key] = true }
    }
    return changed, removed
}
func main() {
    updated, deleted := changes([]Pair{{"ink", 2}, {"paper", 8}}, []Pair{{"ink", 0}, {"thread", 5}})
    fmt.Println(updated, deleted)
}

// Keep the most recent calibration offsets in a fixed-size circular buffer.
// Snapshot order is oldest to newest even after wraparound. Returning a copy
// allows a consumer to annotate its display without corrupting the retained
// values. Construction rejects zero capacity instead of deferring a division
// error until insertion.

package main

import "fmt"

type Ring struct { data []int; next, count int }
func NewRing(capacity int) (*Ring, error) {
    if capacity <= 0 { return nil, fmt.Errorf("capacity must be positive") }
    return &Ring{data: make([]int, capacity)}, nil
}
func (r *Ring) Push(value int) {
    r.data[r.next] = value
    r.next = (r.next+1) % len(r.data)
    if r.count < len(r.data) { r.count++ }
}
func (r *Ring) Snapshot() []int {
    result := make([]int, 0, r.count)
    start := (r.next-r.count+len(r.data)) % len(r.data)
    for i := 0; i < r.count; i++ { result = append(result, r.data[(start+i)%len(r.data)]) }
    return result
}
func main() {
    ring, _ := NewRing(3)
    for _, value := range []int{7, 9, 2, 6} { ring.Push(value) }
    first := ring.Snapshot(); first[0] = -1
    fmt.Println(first, ring.Snapshot())
}

// Traverse uneven rows of a mosaic in alternating directions. Empty rows
// still contribute to the row index and therefore affect which direction the
// next row uses. Prefix offsets describe the ordinary row-wise layout
// separately from the zigzag traversal. No rectangular shape is required.

package main

import "fmt"

func zigzag(rows [][]int) []int {
    output := []int{}
    for index, row := range rows {
        if index%2 == 0 { output = append(output, row...); continue }
        for column := len(row)-1; column >= 0; column-- { output = append(output, row[column]) }
    }
    return output
}
func rowOffsets(rows [][]int) []int {
    result := make([]int, len(rows)+1)
    for i, row := range rows { result[i+1] = result[i]+len(row) }
    return result
}
func main() {
    rows := [][]int{{1, 2, 3}, {}, {4}, {5, 6}}
    order := zigzag(rows)
    offsets := rowOffsets(rows)
    fmt.Println(order, offsets)
    fmt.Println(rows)
    fmt.Println(zigzag(nil), rowOffsets(nil))
}

// Split a valid UTF-8 exhibit label after a fixed number of scalar values.
// Byte offsets come from range iteration, so no split lands inside an
// encoded scalar. This is not grapheme segmentation: combining marks and
// joined emoji can still be separated. Invalid byte strings receive an
// explicit error.

package main

import ("fmt"; "unicode/utf8")

func runeChunks(text string, width int) ([]string, error) {
    if width <= 0 { return nil, fmt.Errorf("positive width required") }
    if !utf8.ValidString(text) { return nil, fmt.Errorf("invalid UTF-8") }
    chunks := []string{}
    start, count := 0, 0
    for offset := range text {
        if count == width { chunks = append(chunks, text[start:offset]); start = offset; count = 0 }
        count++
    }
    if start < len(text) { chunks = append(chunks, text[start:]) }
    return chunks, nil
}
func main() {
    chunks, err := runeChunks("oak-雪-cloud", 3)
    fmt.Println(chunks, err)
    empty, _ := runeChunks("", 2)
    fmt.Println(len(empty))
    _, invalid := runeChunks(string([]byte{255}), 2)
    fmt.Println(invalid != nil)
}

// Compute a bounding rectangle around drawing coordinates, then
// test inclusive membership. Negative coordinates need no special case. The
// validity flag prevents an empty point cloud from being confused with a
// real rectangle at the origin. A point on any boundary is considered inside
// by design.

package main

import "fmt"

type Point struct { X, Y int }
func boundary(points []Point) (Point, Point, bool) {
    if len(points) == 0 { return Point{}, Point{}, false }
    low, high := points[0], points[0]
    for _, point := range points[1:] {
        if point.X < low.X { low.X = point.X }
        if point.Y < low.Y { low.Y = point.Y }
        if point.X > high.X { high.X = point.X }
        if point.Y > high.Y { high.Y = point.Y }
    }
    return low, high, true
}
func inside(point, low, high Point) bool {
    return low.X <= point.X && point.X <= high.X && low.Y <= point.Y && point.Y <= high.Y
}
func main() {
    low, high, ok := boundary([]Point{{-4, 2}, {8, -1}, {0, 9}})
    fmt.Println(low, high, ok)
    fmt.Println(inside(Point{0, 0}, low, high))
    _, _, empty := boundary(nil)
    fmt.Println(empty)
}

// Count metal components in sorted key order. Converting each
// quantity to a wider integer type before aggregation avoids a narrow per-
// entry sum. Filtering above a threshold borrows the completed map and
// leaves it unchanged. Map order is deterministic and does not depend on
// randomized hash iteration.

use std::collections::BTreeMap;

fn grouped_counts<'a>(items: &'a [(&'a str, u32)]) -> BTreeMap<&'a str, u64> {
    let mut totals = BTreeMap::new();
    for &(key, count) in items {
        *totals.entry(key).or_insert(0) += u64::from(count);
    }
    totals
}
fn above_limit<'a>(counts: &BTreeMap<&'a str, u64>, limit: u64) -> Vec<(&'a str, u64)> {
    counts.iter().filter_map(|(&key, &value)| {
        if value > limit { Some((key, value)) } else { None }
    }).collect()
}
fn main() {
    let rows = [("copper", 3), ("zinc", 0), ("copper", 5)];
    let counts = grouped_counts(&rows);
    assert_eq!(counts["copper"], 8);
    assert_eq!(above_limit(&counts, 4), vec![("copper", 8)]);
    assert!(grouped_counts(&[]).is_empty());
    println!("{:?}", counts);
}

// Apply a series of elevator-model displacements while checking both
// arithmetic overflow and permitted floor bounds. These are different error
// conditions. Successful output includes the initial position and every
// later position. The function returns no misleading partial success when a
// later move violates the declared constraints.

fn bounded_steps(start: i64, changes: &[i64], low: i64, high: i64) -> Result<Vec<i64>, &'static str> {
    if low > high || start < low || start > high { return Err("invalid bounds"); }
    let mut current = start;
    let mut states = vec![start];
    for &change in changes {
        current = current.checked_add(change).ok_or("integer overflow")?;
        if current < low || current > high { return Err("outside bounds"); }
        states.push(current);
    }
    Ok(states)
}
fn main() {
    assert_eq!(bounded_steps(5, &[2, -4, 1], 0, 10), Ok(vec![5, 7, 3, 4]));
    assert_eq!(bounded_steps(5, &[6], 0, 10), Err("outside bounds"));
    assert_eq!(bounded_steps(i64::MAX, &[1], 0, i64::MAX), Err("integer overflow"));
    println!("{:?}", bounded_steps(0, &[], 0, 0));
}

// Find the longest constant section in a water-level record. Tied
// sections retain the earlier location. The result uses an exclusive end
// index suitable for slicing, and empty input has no section at all.
// Including the final boundary in the scan closes a plateau that reaches the
// end.

fn longest_plateau(values: &[i32]) -> Option<(usize, usize)> {
    if values.is_empty() { return None; }
    let mut best = (0, 1);
    let mut start = 0;
    for end in 1..=values.len() {
        if end == values.len() || values[end] != values[start] {
            if end - start > best.1 - best.0 { best = (start, end); }
            start = end;
        }
    }
    Some(best)
}
fn main() {
    let levels = [2, 2, 7, 7, 7, 3, 3, 3];
    let (start, end) = longest_plateau(&levels).unwrap();
    assert_eq!((start, end), (2, 5));
    assert_eq!(&levels[start..end], &[7, 7, 7]);
    assert_eq!(longest_plateau(&[]), None);
    assert_eq!(longest_plateau(&[9]), Some((0, 1)));
    println!("{}..{}", start, end);
}

// List unused positions in a small display rack, then compress adjacent free
// positions into intervals. Repeated occupied positions do not consume
// additional capacity. Out-of-range positions are rejected rather than
// clipped. The interval helper expects sorted input, a condition satisfied
// by the rack scan that precedes it.

use std::collections::BTreeSet;

fn missing_slots(taken: &[usize], capacity: usize) -> Result<Vec<usize>, &'static str> {
    let mut occupied = BTreeSet::new();
    for &slot in taken {
        if slot >= capacity { return Err("slot outside capacity"); }
        occupied.insert(slot);
    }
    Ok((0..capacity).filter(|slot| !occupied.contains(slot)).collect())
}
fn contiguous_groups(slots: &[usize]) -> Vec<(usize, usize)> {
    let mut result: Vec<(usize, usize)> = Vec::new();
    for &slot in slots {
        if let Some(last) = result.last_mut() {
            if last.1 == slot { last.1 += 1; continue; }
        }
        result.push((slot, slot + 1));
    }
    result
}
fn main() {
    let free = missing_slots(&[0, 3, 3, 7], 9).unwrap();
    assert_eq!(contiguous_groups(&free), vec![(1, 3), (4, 7), (8, 9)]);
    assert!(missing_slots(&[9], 9).is_err());
}

// Read a materials ledger with one name and signed integer per
// nonblank line. Diagnostics refer to original line numbers, including
// skipped blank lines. An empty name is rejected. Splitting only once lets
// an extra delimiter remain in the numeric field, where strict integer
// parsing catches it.

fn strict_pairs(input: &str) -> Result<Vec<(&str, i64)>, String> {
    let mut result = Vec::new();
    for (index, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() { continue; }
        let (name, number) = line.split_once(':').ok_or_else(|| format!("line {}: delimiter", index + 1))?;
        let name = name.trim();
        if name.is_empty() { return Err(format!("line {}: empty name", index + 1)); }
        let number = number.trim().parse::<i64>().map_err(|_| format!("line {}: number", index + 1))?;
        result.push((name, number));
    }
    Ok(result)
}
fn main() {
    assert_eq!(strict_pairs(" spool: 3\n\nclip: -1").unwrap(), vec![("spool", 3), ("clip", -1)]);
    assert!(strict_pairs("name: 2: 3").is_err());
    assert!(strict_pairs(": 5").is_err());
}

// Calculate relative changes between adjacent balance readings.
// The absolute magnitude of the earlier reading is the denominator, keeping
// the change direction meaningful for negative starting values. Zero
// denominators and nonfinite results are represented as None. Finite inputs
// still receive a postcalculation overflow check.

fn relative_changes(values: &[f64]) -> Vec<Option<f64>> {
    values.windows(2).map(|pair| {
        let (before, after) = (pair[0], pair[1]);
        if before == 0.0 || !before.is_finite() || !after.is_finite() {
            None
        } else {
            let change = (after - before) / before.abs();
            if change.is_finite() { Some(change) } else { None }
        }
    }).collect()
}
fn main() {
    let values = [4.0, 6.0, 0.0, -2.0, -1.0];
    let result = relative_changes(&values);
    assert_eq!(result, vec![Some(0.5), Some(-1.0), None, Some(0.5)]);
    assert!(relative_changes(&[]).is_empty());
    assert_eq!(relative_changes(&[f64::NAN, 2.0]), vec![None]);
    println!("{:?}", result);
}

// Visit a ragged grid along increasing row-plus-column diagonals. Missing
// cells are skipped instead of being replaced by a fabricated value.
// Borrowing the rows preserves their contents. A completely empty grid and
// an empty row before a later value are both covered by the examples.

fn diagonal_order(rows: &[Vec<i32>]) -> Vec<i32> {
    let max_sum = rows.iter().enumerate().map(|(r, row)| r + row.len()).max().unwrap_or(0);
    let mut result = Vec::new();
    for sum in 0..max_sum {
        for (row_index, row) in rows.iter().enumerate() {
            if sum < row_index { continue; }
            let column = sum - row_index;
            if let Some(&value) = row.get(column) { result.push(value); }
        }
    }
    result
}
fn main() {
    let shape = vec![vec![1, 2, 3], vec![4], vec![5, 6]];
    assert_eq!(diagonal_order(&shape), vec![1, 2, 4, 3, 5, 6]);
    assert_eq!(diagonal_order(&[vec![], vec![8]]), vec![8]);
    assert!(diagonal_order(&[]).is_empty());
    println!("{:?}", shape);
}

// Divide indivisible tokens in proportion to declared weights, distributing
// leftover units by largest remainder. Input position resolves equal
// remainders. A zero-weight recipient stays present with zero tokens, while
// all-zero weights are invalid. Intermediate multiplication uses a wider
// type before integer division.

fn split_budget(total: u64, weights: &[u64]) -> Result<Vec<u64>, &'static str> {
    let sum: u128 = weights.iter().map(|&value| u128::from(value)).sum();
    if sum == 0 { return Err("zero weight"); }
    let mut shares = Vec::new();
    let mut fractions = Vec::new();
    let mut assigned = 0;
    for (index, &weight) in weights.iter().enumerate() {
        let scaled = u128::from(total) * u128::from(weight);
        let share = (scaled / sum) as u64;
        shares.push(share); assigned += share;
        fractions.push((scaled % sum, index));
    }
    fractions.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
    for &(_, index) in fractions.iter().take((total-assigned) as usize) { shares[index] += 1; }
    Ok(shares)
}
fn main() {
    assert_eq!(split_budget(10, &[1, 1, 1]), Ok(vec![4, 3, 3]));
    assert_eq!(split_budget(5, &[0, 2]), Ok(vec![0, 5]));
}

// Advance a multiset arrangement to its next lexicographic ordering.
// Repeated values do not produce duplicate permutations. On the final
// ordering, the function restores the initial sorted order and returns
// false. That mutation is part of the interface and is checked rather than
// assumed away.

fn next_permutation(values: &mut [i32]) -> bool {
    if values.len() < 2 { return false; }
    let pivot = (0..values.len()-1).rev().find(|&i| values[i] < values[i+1]);
    let Some(pivot) = pivot else { values.reverse(); return false; };
    let successor = (pivot+1..values.len()).rev().find(|&i| values[i] > values[pivot]).unwrap();
    values.swap(pivot, successor);
    values[pivot+1..].reverse();
    true
}
fn main() {
    let mut order = [1, 1, 2];
    let mut observed = vec![order.to_vec()];
    while next_permutation(&mut order) { observed.push(order.to_vec()); }
    assert_eq!(observed, vec![vec![1, 1, 2], vec![1, 2, 1], vec![2, 1, 1]]);
    assert_eq!(order, [1, 1, 2]);
    assert!(!next_permutation(&mut []));
}

// Extract nonempty sections of a route label while recording their
// original UTF-8 byte ranges. A multibyte character occupies more than one
// byte, and the returned bounds remain valid slicing positions. Consecutive
// separators and a trailing separator are skipped without manufacturing
// empty sections.

#[derive(Debug, PartialEq)]
struct Segment { start: usize, end: usize, text: String }
fn nonempty_segments(input: &str, separator: char) -> Vec<Segment> {
    let mut output = Vec::new();
    let mut start = 0;
    for (offset, ch) in input.char_indices() {
        if ch == separator {
            if start < offset { output.push(Segment { start, end: offset, text: input[start..offset].to_owned() }); }
            start = offset + ch.len_utf8();
        }
    }
    if start < input.len() { output.push(Segment { start, end: input.len(), text: input[start..].to_owned() }); }
    output
}
fn main() {
    let input = "oak||雪|";
    let parts = nonempty_segments(input, '|');
    assert_eq!(parts.len(), 2);
    assert_eq!(&input[parts[1].start..parts[1].end], "雪");
    println!("{:?}", parts);
}

-- List the most popular choices in each ballot batch, preserving
-- ties. Blank choices are excluded from votes but included in the returned-
-- ballot count. Dense ranking selects all joint leaders. The winner table
-- alone cannot supply a percentage of all invited participants because that
-- denominator is not recorded.

CREATE TABLE ballots (seq INTEGER PRIMARY KEY, batch TEXT, choice TEXT);
INSERT INTO ballots VALUES
 (1,'morning','garden'),(2,'morning','studio'),(3,'morning','garden'),
 (4,'evening','studio'),(5,'evening',NULL),(6,'evening','studio'),(7,'evening','garden');
WITH counted AS (
 SELECT batch,choice,COUNT(*) AS votes
 FROM ballots WHERE choice IS NOT NULL GROUP BY batch,choice
), ranked AS (
 SELECT batch,choice,votes,
        DENSE_RANK() OVER (PARTITION BY batch ORDER BY votes DESC) AS place
 FROM counted
)
SELECT batch,choice,votes FROM ranked WHERE place=1 ORDER BY batch,choice;

SELECT batch,COUNT(*) AS returned,COUNT(choice) AS usable FROM ballots GROUP BY batch ORDER BY batch;

-- Calculate remaining craft material after aggregating usage by purchase
-- batch. Joining raw usage rows directly to purchases would repeat purchased
-- quantities, so the aggregation happens first. Left joins preserve unused
-- batches. A batch with zero initial quantity can still be classified as
-- having no recorded use.

CREATE TABLE batches (id INTEGER PRIMARY KEY, material TEXT, amount INTEGER);
CREATE TABLE uses (batch_id INTEGER, amount INTEGER);
INSERT INTO batches VALUES (1,'paper',20),(2,'paper',12),(3,'cord',8),(4,'ink',0);
INSERT INTO uses VALUES (1,4),(1,3),(3,8);
WITH consumed AS (
 SELECT batch_id,SUM(amount) AS total FROM uses GROUP BY batch_id
), remaining AS (
 SELECT b.id,b.material,b.amount-COALESCE(c.total,0) AS available
 FROM batches AS b LEFT JOIN consumed AS c ON c.batch_id=b.id
)
SELECT material,SUM(available) AS available,COUNT(*) AS batch_count
FROM remaining GROUP BY material ORDER BY material;

SELECT b.id FROM batches AS b
WHERE NOT EXISTS (SELECT 1 FROM uses AS u WHERE u.batch_id=b.id)
ORDER BY b.id;

-- Group same-topic observations separated by no more than eight minutes. A
-- lag identifies long gaps, and a cumulative sum converts start markers into
-- group identifiers. The stable ordering includes an event identifier for
-- tied times. Interleaved observations of another topic do not break a
-- topic-specific group.

CREATE TABLE sessions (id INTEGER PRIMARY KEY, topic TEXT, minute INTEGER);
INSERT INTO sessions VALUES (1,'clay',10),(2,'clay',15),(3,'clay',28),(4,'ink',11),(5,'ink',14),(6,'clay',30);
WITH gaps AS (
 SELECT id,topic,minute,
        minute-LAG(minute) OVER (PARTITION BY topic ORDER BY minute,id) AS gap
 FROM sessions
), marks AS (
 SELECT *,CASE WHEN gap IS NULL OR gap>8 THEN 1 ELSE 0 END AS starts_group FROM gaps
), grouped AS (
 SELECT *,SUM(starts_group) OVER (PARTITION BY topic ORDER BY minute,id) AS group_id FROM marks
)
SELECT topic,group_id,MIN(minute) AS first_minute,MAX(minute) AS last_minute,COUNT(*) AS entries
FROM grouped GROUP BY topic,group_id ORDER BY topic,group_id;

-- Contrast two meanings of latest active revision. Selecting the latest
-- revision before excluding withdrawn items removes retired objects;
-- excluding withdrawn rows first can resurrect an older version. Both
-- queries are syntactically valid but implement different policies. The
-- small example makes that semantic difference visible.

CREATE TABLE revisions (item TEXT, revision INTEGER, label TEXT, withdrawn INTEGER,
 PRIMARY KEY(item,revision));
INSERT INTO revisions VALUES
 ('map',1,'rough',0),('map',2,'clean',0),('map',3,'retired',1),
 ('card',1,'plain',0),('card',2,'large',0),('tag',1,'blue',1);
WITH latest AS (
 SELECT *,ROW_NUMBER() OVER (PARTITION BY item ORDER BY revision DESC) AS position
 FROM revisions
)
SELECT item,revision,label FROM latest WHERE position=1 AND withdrawn=0 ORDER BY item;

WITH last_active AS (
 SELECT *,ROW_NUMBER() OVER (PARTITION BY item ORDER BY revision DESC) AS position
 FROM revisions WHERE withdrawn=0
)
SELECT item,revision,label FROM last_active WHERE position=1 ORDER BY item;

-- Compare declared capacity with booking totals while retaining
-- empty slots. Negative remaining capacity is preserved to reveal
-- overbooking. A final query identifies a single party larger than its slot
-- capacity, which is distinct from several individually valid parties
-- exceeding capacity together.

CREATE TABLE schedule (slot INTEGER PRIMARY KEY, capacity INTEGER NOT NULL);
CREATE TABLE bookings (id INTEGER PRIMARY KEY, slot INTEGER, seats INTEGER CHECK(seats>0));
INSERT INTO schedule VALUES (1,8),(2,6),(3,5),(4,0);
INSERT INTO bookings VALUES (1,1,3),(2,1,2),(3,2,7);
WITH reserved AS (
 SELECT slot,SUM(seats) AS taken,COUNT(*) AS groups FROM bookings GROUP BY slot
)
SELECT s.slot,s.capacity,COALESCE(r.taken,0) AS taken,
       s.capacity-COALESCE(r.taken,0) AS remaining,
       CASE WHEN COALESCE(r.taken,0)>s.capacity THEN 'overbooked' ELSE 'within-limit' END AS status
FROM schedule AS s LEFT JOIN reserved AS r ON r.slot=s.slot
ORDER BY s.slot;

SELECT slot,seats FROM bookings WHERE seats>(SELECT capacity FROM schedule WHERE schedule.slot=bookings.slot);
